"use client";

import * as React from "react";
import type { Locale } from "date-fns";
import * as PopoverPrimitive from "@radix-ui/react-popover";
import {
  useFilterTokens,
  type FilterSchema,
  type FilterTokensProps,
} from "filter-tokens";
import { Trigger } from "./parts/trigger";
import { Header } from "./parts/header";
import { Listbox } from "./parts/listbox";
import { Panels } from "./parts/panels";

/* ─── Types ────────────────────────────────────────────────────────────────── */

type FilterTokensComponentProps<T extends FilterSchema> = FilterTokensProps<T> &
  Omit<React.ComponentProps<"div">, "onChange"> & {
    dateLocale?: Locale;
  };

/* ─── FilterTokens ─────────────────────────────────────────────────────────── */

function FilterTokens<const T extends FilterSchema>({
  filters,
  value,
  onChange,
  placeholder = "Filter...",
  className,
  disabled,
  dateLocale,
  ...props
}: FilterTokensComponentProps<T>) {
  const ft = useFilterTokens({
    filters,
    value,
    onChange,
    placeholder,
    locale: dateLocale?.code,
  });
  const listboxId = React.useId();
  const popoverContentId = React.useId();

  const { mode, category: activeCategory } = ft.dropdown.state;
  const isTextEntry = mode === "text-entry";
  const isDateEntry = mode === "date-entry";
  const isPanelMode = isDateEntry || mode === "number-entry";

  const activeDef = activeCategory
    ? (filters as FilterSchema)[activeCategory]
    : null;
  const activeLabel = activeDef?.label ?? null;
  const isMultiSelect =
    activeDef?.type === "select" && activeDef.multi === true;

  return (
    <PopoverPrimitive.Root
      open={ft.dropdown.open}
      onOpenChange={(open) => { if (!open) ft.dropdown.close(); }}
      modal={false}
    >
      <PopoverPrimitive.Anchor asChild>
        <div data-slot="filter-tokens" {...props}>
          <Trigger
            ft={ft}
            listboxId={listboxId}
            disabled={disabled}
            className={className}
          />
        </div>
      </PopoverPrimitive.Anchor>

      <PopoverPrimitive.Portal>
        <PopoverPrimitive.Content
          id={popoverContentId}
          data-slot="filter-tokens-dropdown"
          data-state={mode}
          align="start"
          sideOffset={4}
          className="z-50 max-w-[480px] min-w-(--radix-popover-trigger-width) rounded-lg border border-border bg-popover p-0 text-popover-foreground shadow-lg outline-none"
          onOpenAutoFocus={(e) => e.preventDefault()}
          onCloseAutoFocus={(e) => e.preventDefault()}
          onInteractOutside={(e) => {
            // The combobox input lives in the trigger area, not in the popover
            // content. When focus moves to it (after a chip click or option
            // selection), Radix would otherwise treat that as an outside
            // interaction and close. Keep it open for any interaction inside
            // our trigger surface.
            const target = e.target as Element | null;
            if (target?.closest?.('[data-slot="filter-tokens-trigger"]')) {
              e.preventDefault();
            }
          }}
          onEscapeKeyDown={(e) => {
            // Radix's escape listener fires in document capture phase, so it
            // runs *before* the hook's handleKeyDown (which is the input's
            // onKeyDown bubble). React 19 flushes setState between phases,
            // which means the hook would see the *new* mode and advance a
            // second time (values → categories → close).
            //
            // To make ESC behave correctly:
            //  - In sub-modes (values / text-entry / panel): goBack here and
            //    preventDefault so Radix doesn't dismiss. The hook then
            //    short-circuits because e.defaultPrevented === true.
            //  - In categories mode: do nothing here — let Radix's default
            //    dismiss path run (calls onOpenChange(false)), which closes.
            if (mode === "values" || mode === "text-entry" || isPanelMode) {
              e.preventDefault();
              ft.dropdown.goBack();
            }
          }}
        >
          {activeLabel && (
            <Header
              activeLabel={activeLabel}
              isDateEntry={isDateEntry}
              onBack={ft.dropdown.goBack}
            />
          )}

          {!isPanelMode && (
            <Listbox
              ft={ft}
              listboxId={listboxId}
              activeLabel={activeLabel}
              isMultiSelect={isMultiSelect}
              isTextEntry={isTextEntry}
            />
          )}

          {isPanelMode && (
            <Panels
              ft={ft}
              filters={filters}
              value={value}
              dateLocale={dateLocale}
            />
          )}
        </PopoverPrimitive.Content>
      </PopoverPrimitive.Portal>
    </PopoverPrimitive.Root>
  );
}

/* ─── Exports ──────────────────────────────────────────────────────────────── */

export { FilterTokens };
export type { FilterTokensComponentProps };

"use client";

import * as React from "react";
import { XIcon } from "lucide-react";
import type { FilterSchema, FilterTokensReturn } from "filter-tokens";
import { cn } from "@/lib/utils";
import { Chip } from "./chip";

export interface TriggerProps<T extends FilterSchema> {
  ft: FilterTokensReturn<T>;
  /**
   * ID of the listbox element rendered inside the popover content.
   * Used for `aria-controls` and to compute the highlighted option ID
   * for `aria-activedescendant`.
   */
  listboxId: string;
  disabled?: boolean;
  className?: string;
}

export function Trigger<T extends FilterSchema>({
  ft,
  listboxId,
  disabled,
  className,
}: TriggerProps<T>) {
  const chipRefs = React.useRef<(HTMLSpanElement | null)[]>([]);

  const isPanelMode =
    ft.dropdown.state.mode === "date-entry" ||
    ft.dropdown.state.mode === "number-entry";

  // When the popover opens (via chip click, keyboard, or programmatic open()),
  // make sure focus lands on our outer input — except in date/number entry
  // where the panel manages its own focus.
  React.useEffect(() => {
    if (ft.dropdown.open && !isPanelMode) {
      requestAnimationFrame(() => ft.inputProps.ref.current?.focus());
    }
  }, [ft.dropdown.open, ft.dropdown.state.mode, isPanelMode, ft.inputProps.ref]);

  const highlightedItem =
    ft.dropdown.highlightedIndex >= 0
      ? ft.dropdown.items[ft.dropdown.highlightedIndex]
      : null;
  const activeDescendantId =
    ft.dropdown.open && highlightedItem
      ? `${listboxId}-item-${highlightedItem.key}`
      : undefined;

  function handleWrapperMouseDown(e: React.MouseEvent<HTMLDivElement>) {
    if (disabled) return;
    const target = e.target as HTMLElement;
    if (
      target.closest("[data-slot=filter-tokens-token]") ||
      target.closest("[data-slot=filter-tokens-clear]") ||
      target.tagName === "INPUT"
    ) {
      return;
    }
    e.preventDefault();
    ft.inputProps.ref.current?.focus();
  }

  return (
    <>
      <div
        data-slot="filter-tokens-announcement"
        role="status"
        aria-live="polite"
        className="sr-only"
      >
        {ft.announcement}
      </div>
      <div
        data-slot="filter-tokens-trigger"
        data-disabled={disabled || undefined}
        className={cn(
          "flex min-h-10 w-full flex-wrap items-center gap-1.5 rounded-lg border border-input bg-background px-3 py-2 text-sm cursor-text",
          "focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-2 focus-within:ring-offset-background",
          disabled && "cursor-not-allowed opacity-50",
          className,
        )}
        onMouseDown={handleWrapperMouseDown}
      >
        {ft.tokens.map((token, index) => (
          <Chip
            key={token.id}
            ref={(el) => {
              chipRefs.current[index] = el;
            }}
            category={token.category}
            label={token.label}
            displayValue={token.displayValue}
            onRemove={() => {
              const removeIndex = index;
              const expectedCount = ft.tokens.length - 1;
              token.remove();
              requestAnimationFrame(() => {
                const nextChip =
                  removeIndex < expectedCount
                    ? chipRefs.current[removeIndex]
                    : null;
                const prevChip =
                  removeIndex > 0
                    ? chipRefs.current[removeIndex - 1]
                    : null;
                (nextChip ?? prevChip ?? ft.inputProps.ref.current)?.focus();
              });
            }}
            onClick={() => ft.openCategory(token.category)}
            disabled={disabled}
          />
        ))}

        <input
          {...ft.inputProps}
          data-slot="filter-tokens-input"
          disabled={disabled}
          // Panel modes (date / number) render a dialog, not a listbox, so
          // the popup type and the controlled element id both differ.
          aria-haspopup={isPanelMode ? "dialog" : "listbox"}
          aria-controls={
            ft.dropdown.open && !isPanelMode ? listboxId : undefined
          }
          aria-activedescendant={activeDescendantId}
          onClick={() => {
            // Focus alone won't reopen the popover after ESC-from-categories
            // (the input keeps focus, so onFocus doesn't re-fire). A click
            // on the input bar always opens.
            if (!disabled && !ft.dropdown.open) ft.open();
          }}
          onKeyDown={(e) => {
            // Tab from the open combobox: close the popover so default Tab
            // proceeds to the next focusable element on the page (instead of
            // landing on the popover content's tab-stop). Don't preventDefault.
            if (e.key === "Tab" && ft.dropdown.open) {
              ft.dropdown.close();
            }
            ft.inputProps.onKeyDown(e);
          }}
          className="flex-1 min-w-[120px] border-0 bg-transparent p-0 text-sm outline-none placeholder:text-muted-foreground"
        />

        {ft.tokens.length > 0 && (
          <button
            type="button"
            data-slot="filter-tokens-clear"
            tabIndex={-1}
            className="ml-auto shrink-0 rounded-sm p-0.5 text-muted-foreground/60 transition-colors hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            onMouseDown={(e) => e.stopPropagation()}
            onClick={(e) => {
              e.stopPropagation();
              ft.clear();
              // ft.clear() closes the popover and removes the clear button
              // itself, so DOM focus would otherwise fall to <body>. Move
              // focus back to the input so the user can keep typing.
              ft.inputProps.ref.current?.focus();
            }}
            aria-label="Clear all filters"
            disabled={disabled}
          >
            <XIcon className="size-4" />
          </button>
        )}
      </div>
    </>
  );
}

"use client";

import * as React from "react";
import { XIcon } from "lucide-react";
import { cn } from "@/lib/utils";

/**
 * Visual rendering of a Token. Distinct from the `Token` data type
 * exported from the package — that's the value object (id, category,
 * label, displayValue, remove); this is the chip-shaped UI element.
 */
export interface ChipProps {
  category: string;
  label: string;
  displayValue: string;
  onRemove: () => void;
  onClick?: () => void;
  disabled?: boolean;
}

export const Chip = React.forwardRef<
  HTMLSpanElement,
  ChipProps
>(function Chip(
  { category, label, displayValue, onRemove, onClick, disabled },
  ref,
) {
  return (
    <span
      ref={ref}
      data-slot="filter-tokens-token"
      data-category={category}
      role="button"
      tabIndex={0}
      aria-label={`${label}: ${displayValue}. Click to edit.`}
      className="group inline-flex cursor-pointer items-center gap-1 rounded-md bg-secondary py-0.5 pl-2 pr-1 text-xs font-medium text-secondary-foreground transition-colors hover:bg-secondary/80 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
      onClick={(e) => {
        e.stopPropagation();
        if (!disabled && onClick) onClick();
      }}
      onMouseDown={(e) => {
        // Prevent the trigger wrapper's mousedown-to-focus-input handler
        // from stealing focus before the chip's click runs.
        e.stopPropagation();
      }}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          e.stopPropagation();
          if (!disabled && onClick) onClick();
        }
      }}
    >
      <span
        data-slot="filter-tokens-token-label"
        className="text-muted-foreground"
      >
        {label}:
      </span>
      <span data-slot="filter-tokens-token-value">{displayValue}</span>
      <button
        type="button"
        data-slot="filter-tokens-token-remove"
        tabIndex={-1}
        className="ml-0.5 rounded-sm p-0.5 text-muted-foreground/80 transition-colors hover:bg-secondary-foreground/10 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        onClick={(e) => {
          e.stopPropagation();
          onRemove();
        }}
        onMouseDown={(e) => {
          // Same: don't let the trigger wrapper steal focus to the input
          // before the remove handler runs.
          e.stopPropagation();
        }}
        aria-label={`Remove ${label}: ${displayValue}`}
        disabled={disabled}
      >
        <XIcon className="size-3" />
      </button>
    </span>
  );
});

"use client";

import { CalendarIcon, CheckIcon } from "lucide-react";
import { cn } from "@/lib/utils";

export interface ItemIndicatorProps {
  item: { key: string; type: string; selected: boolean };
  isMultiSelect: boolean;
}

export function ItemIndicator({ item, isMultiSelect }: ItemIndicatorProps) {
  if (item.key === "__custom_date__") {
    return <CalendarIcon className="size-4 shrink-0 text-muted-foreground" />;
  }

  if (item.type !== "value") return null;

  if (isMultiSelect) {
    return (
      <div
        className={cn(
          "flex size-4 shrink-0 items-center justify-center rounded-sm border transition-colors",
          item.selected
            ? "border-primary bg-primary text-primary-foreground"
            : "border-input",
        )}
      >
        {item.selected && <CheckIcon className="size-3" />}
      </div>
    );
  }

  return (
    <div
      className={cn(
        "flex size-4 shrink-0 items-center justify-center rounded-full border transition-colors",
        item.selected ? "border-primary" : "border-input",
      )}
    >
      {item.selected && <div className="size-2 rounded-full bg-primary" />}
    </div>
  );
}

"use client";

import * as React from "react";
import type { Locale } from "date-fns";
import { Button } from "@/components/ui/button";
import { Calendar, CalendarDayButton } from "@/components/ui/calendar";
import { DateTimeRow } from "./date-time-row";

export interface RangeCalendarPanelProps {
  showTime: boolean;
  locale?: Locale;
  initialValue?: { from?: string; to?: string };
  onSelect: (value: { from?: string; to?: string }) => void;
  onCancel: () => void;
}

export function RangeCalendarPanel({
  showTime,
  locale,
  initialValue,
  onSelect,
  onCancel,
}: RangeCalendarPanelProps) {
  const [from, setFrom] = React.useState<Date | undefined>(() =>
    initialValue?.from ? new Date(initialValue.from) : undefined,
  );
  const [to, setTo] = React.useState<Date | undefined>(() =>
    initialValue?.to ? new Date(initialValue.to) : undefined,
  );
  const [month, setMonth] = React.useState<Date>(() => from ?? new Date());
  const [activeField, setActiveField] = React.useState<"start" | "end">(
    "start",
  );
  const [hoveredDay, setHoveredDay] = React.useState<Date | undefined>();
  const endInputRef = React.useRef<HTMLInputElement>(null);

  function handleDayClick(day: Date) {
    setHoveredDay(undefined);
    // Calendar clicks produce midnight timestamps — compare dates only
    const dayDate = new Date(day.getFullYear(), day.getMonth(), day.getDate()).getTime();
    const fromDate = from
      ? new Date(from.getFullYear(), from.getMonth(), from.getDate()).getTime()
      : undefined;

    if (activeField === "start") {
      setFrom(day);
      setTo(undefined);
      setActiveField("end");
    } else {
      if (fromDate !== undefined && dayDate < fromDate) {
        // Clicked before start date while End is active — reset start, clear end
        setFrom(day);
        setTo(undefined);
      } else {
        const d = new Date(day);
        if (showTime && d.getHours() === 0 && d.getMinutes() === 0) {
          d.setHours(23, 59, 59, 999);
        }
        setTo(d);
        setActiveField("start");
      }
    }
  }

  function handleApply() {
    if (!from && !to) return;
    if (from && !to) {
      // Open-ended "Since X"
      onSelect({ from: from.toISOString() });
      return;
    }
    if (!from && to) {
      // Open-ended "Until X"
      const toDate = new Date(to);
      if (!showTime) toDate.setHours(23, 59, 59, 999);
      onSelect({ to: toDate.toISOString() });
      return;
    }
    const toDate = new Date(to!);
    if (!showTime) toDate.setHours(23, 59, 59, 999);
    onSelect({ from: from!.toISOString(), to: toDate.toISOString() });
  }

  // Stable DayButton wrapper for hover tracking
  const DayButtonWithHover = React.useMemo(() => {
    return function HoverDayButton(props: React.ComponentProps<typeof CalendarDayButton>) {
      return (
        <CalendarDayButton
          {...props}
          onMouseEnter={() => setHoveredDay(props.day.date)}
        />
      );
    };
  }, []);

  // Build modifiers for range highlighting on single-mode calendar
  const rangeModifiers = React.useMemo(() => {
    if (!from) return {};

    // Show hover preview when End is active
    const previewEnd =
      activeField === "end" && hoveredDay && hoveredDay >= from
        ? hoveredDay
        : undefined;
    const displayEnd = previewEnd ?? to;

    if (!displayEnd || from.getTime() === displayEnd.getTime()) {
      return { range_start: [from], selected: [from] };
    }
    return {
      range_start: [from],
      range_end: [displayEnd],
      range_middle: { after: from, before: displayEnd },
      selected: [from, displayEnd],
    };
  }, [from, to, hoveredDay, activeField]);

  return (
    <div
      data-slot="filter-tokens-calendar"
      className="border-t border-border"
    >
      <div className="space-y-1 px-3 pb-1 pt-3">
        <DateTimeRow
          label="Start"
          date={from}
          active={activeField === "start"}
          onFocus={() => setActiveField("start")}
          onDateChange={(d) => {
            setFrom(d);
            if (to && d > to) setTo(undefined);
            setMonth(d);
          }}
          onEnter={() => {
            setActiveField("end");
            endInputRef.current?.focus();
          }}
          showTime={showTime}
          locale={locale}
        />
        <DateTimeRow
          label="End"
          date={to}
          active={activeField === "end"}
          onFocus={() => setActiveField("end")}
          onDateChange={(d) => {
            if (showTime && d.getHours() === 0 && d.getMinutes() === 0) {
              d.setHours(23, 59, 59, 999);
            }
            if (from && d < from) {
              setFrom(d);
              setTo(undefined);
            } else {
              setTo(d);
            }
            setMonth(d);
          }}
          inputRef={endInputRef}
          showTime={showTime}
          locale={locale}
        />
      </div>
      <div className="p-2" onMouseLeave={() => setHoveredDay(undefined)}>
        <Calendar
          className="mx-auto"
          showOutsideDays={false}
          locale={locale}
          month={month}
          onMonthChange={setMonth}
          onDayClick={handleDayClick}
          modifiers={rangeModifiers}
          numberOfMonths={2}
          components={{ DayButton: DayButtonWithHover }}
        />
      </div>
      <div className="flex justify-end gap-2 px-3 pb-3">
        <Button variant="ghost" onClick={onCancel}>
          Cancel
        </Button>
        <Button disabled={!from && !to} onClick={handleApply}>
          Apply
        </Button>
      </div>
    </div>
  );
}

export interface SingleCalendarPanelProps {
  showTime: boolean;
  locale?: Locale;
  initialValue?: { date?: string };
  onSelect: (value: { date: string }) => void;
  onCancel: () => void;
}

export function SingleCalendarPanel({
  showTime,
  locale,
  initialValue,
  onSelect,
  onCancel,
}: SingleCalendarPanelProps) {
  const [selected, setSelected] = React.useState<Date | undefined>(() => {
    if (!initialValue?.date) return undefined;
    return new Date(initialValue.date);
  });

  const [month, setMonth] = React.useState<Date>(
    () => selected ?? new Date(),
  );

  function handleApply() {
    if (!selected) return;
    onSelect({ date: selected.toISOString() });
  }

  return (
    <div
      data-slot="filter-tokens-calendar"
      className="border-t border-border"
    >
      <div className="px-3 pb-1 pt-3">
        <DateTimeRow
          label="Date"
          date={selected}
          onDateChange={(d) => {
            setSelected(d);
            setMonth(d);
          }}
          showTime={showTime}
          locale={locale}
        />
      </div>
      <div className="p-2">
        <Calendar
          mode="single"
          className="mx-auto"
          showOutsideDays={false}
          locale={locale}
          month={month}
          onMonthChange={setMonth}
          selected={selected}
          onSelect={(day) => {
            setSelected(day);
            if (day && !showTime) onSelect({ date: day.toISOString() });
          }}
        />
      </div>
      {showTime && (
        <div className="flex justify-end gap-2 px-3 pb-3">
          <Button variant="ghost" onClick={onCancel}>
            Cancel
          </Button>
          <Button disabled={!selected} onClick={handleApply}>
            Apply
          </Button>
        </div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

export interface NumberPanelProps {
  unit?: string;
  min?: number;
  max?: number;
  initialValue?: { min?: number; max?: number };
  onSelect: (value: { min?: number; max?: number }) => void;
  onCancel: () => void;
}

export function NumberPanel({
  unit,
  min,
  max,
  initialValue,
  onSelect,
  onCancel,
}: NumberPanelProps) {
  const [minVal, setMinVal] = React.useState(initialValue?.min?.toString() ?? "");
  const [maxVal, setMaxVal] = React.useState(initialValue?.max?.toString() ?? "");
  const minId = React.useId();
  const maxId = React.useId();

  const parsedMin = minVal ? parseFloat(minVal) : undefined;
  const parsedMax = maxVal ? parseFloat(maxVal) : undefined;
  const hasValidMin = parsedMin !== undefined && !isNaN(parsedMin);
  const hasValidMax = parsedMax !== undefined && !isNaN(parsedMax);
  const hasValue = hasValidMin || hasValidMax;

  function handleApply() {
    if (!hasValue) return;
    const result: { min?: number; max?: number } = {};
    if (hasValidMin) result.min = parsedMin;
    if (hasValidMax) result.max = parsedMax;
    onSelect(result);
  }

  return (
    <div
      data-slot="filter-tokens-number"
      className="border-t border-border p-3 space-y-2"
    >
      <div className="flex items-center gap-2 px-2 py-1 text-sm">
        <label htmlFor={minId} className="w-9 shrink-0 text-xs font-medium text-muted-foreground">
          Min
        </label>
        <input
          id={minId}
          type="number"
          aria-label={`Minimum value${unit ? ` (${unit})` : ""}`}
          className={cn(
            "flex-1 rounded-md border border-input bg-background px-2.5 py-1.5 text-sm font-mono tabular-nums placeholder:text-muted-foreground/40 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-1",
          )}
          placeholder={min !== undefined ? String(min) : ""}
          value={minVal}
          min={min}
          max={max}
          onChange={(e) => setMinVal(e.target.value)}
          onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); handleApply(); } }}
        />
        {unit && <span className="text-xs text-muted-foreground">{unit}</span>}
      </div>
      <div className="flex items-center gap-2 px-2 py-1 text-sm">
        <label htmlFor={maxId} className="w-9 shrink-0 text-xs font-medium text-muted-foreground">
          Max
        </label>
        <input
          id={maxId}
          type="number"
          aria-label={`Maximum value${unit ? ` (${unit})` : ""}`}
          className={cn(
            "flex-1 rounded-md border border-input bg-background px-2.5 py-1.5 text-sm font-mono tabular-nums placeholder:text-muted-foreground/40 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-1",
          )}
          placeholder={max !== undefined ? String(max) : ""}
          value={maxVal}
          min={min}
          max={max}
          onChange={(e) => setMaxVal(e.target.value)}
          onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); handleApply(); } }}
        />
        {unit && <span className="text-xs text-muted-foreground">{unit}</span>}
      </div>
      <div className="flex justify-end gap-2 px-2">
        <Button variant="ghost" onClick={onCancel}>
          Cancel
        </Button>
        <Button disabled={!hasValue} onClick={handleApply}>
          Apply
        </Button>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { format, isValid, parse } from "date-fns";
import { enUS } from "date-fns/locale";
import type { Locale } from "date-fns";
import { cn } from "@/lib/utils";

export interface DateTimeRowProps {
  label: string;
  date: Date | undefined;
  onDateChange: (d: Date) => void;
  showTime: boolean;
  locale?: Locale;
  active?: boolean;
  onFocus?: () => void;
  onEnter?: () => void;
  inputRef?: React.RefObject<HTMLInputElement | null>;
}

export function DateTimeRow({
  label,
  date,
  onDateChange,
  showTime,
  locale,
  active,
  onFocus,
  onEnter,
  inputRef,
}: DateTimeRowProps) {
  const loc = locale ?? enUS;
  const fmt = showTime ? "P p" : "P";
  const ph = format(new Date(2026, 0, 15, 13, 30), fmt, { locale: loc });
  const inputId = React.useId();

  function formatDate(d: Date) {
    return format(d, fmt, { locale: loc });
  }

  function parseInput(v: string): Date | null {
    const t = v.trim();
    if (!t) return null;

    const formats = [fmt, "yyyy-MM-dd HH:mm", "yyyy-MM-dd"];
    for (const f of formats) {
      try {
        const p = parse(t, f, new Date(), { locale: loc });
        if (isValid(p)) return p;
      } catch {
        /* try next format */
      }
    }

    const fallback = new Date(t);
    return isNaN(fallback.getTime()) ? null : fallback;
  }

  const [text, setText] = React.useState(date ? formatDate(date) : "");

  React.useEffect(() => {
    setText(date ? format(date, fmt, { locale: loc }) : "");
  }, [date, fmt, loc]);

  function handleBlur() {
    const parsed = parseInput(text);
    if (!parsed) {
      if (date) setText(formatDate(date));
      return;
    }
    if (!date || formatDate(parsed) !== formatDate(date)) {
      onDateChange(parsed);
    }
  }

  return (
    <div
      data-slot="filter-tokens-date-input"
      className="flex items-center gap-2 px-2 py-1 text-sm"
    >
      <label
        htmlFor={inputId}
        className="w-9 shrink-0 text-xs font-medium text-muted-foreground"
      >
        {label}
      </label>
      <input
        id={inputId}
        ref={inputRef}
        type="text"
        aria-label={`${label} date${showTime ? " and time" : ""}`}
        className={cn(
          "flex-1 rounded-md border bg-background px-2.5 py-1.5 text-sm font-mono tabular-nums placeholder:text-muted-foreground/40 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-1",
          active ? "border-ring ring-2 ring-ring ring-offset-1" : "border-input",
        )}
        placeholder={ph}
        value={text}
        onChange={(e) => setText(e.target.value)}
        onFocus={onFocus}
        onBlur={handleBlur}
        onKeyDown={(e) => {
          if (e.key === "Enter") {
            e.preventDefault();
            handleBlur();
            onEnter?.();
          }
        }}
      />
    </div>
  );
}
